    /// <summary>social</summary>
    public class D001_social
    {

        [Fact(DisplayName = "social > rises in company and sinks alone; lonely people feel it")]
        public void T002_rises_in_company_and_sinks_alone_lonely_people_feel_it()
        {
            var state = ScenarioMod.loadScenario(new Scenario { seed = 1, map = ["s.s.........s"] });
            var (a, b, c) = state.survivors;
            for (var i = 0; i < 20; i++)
            {
                state.tick = Js.I(((double)((i + 1)) * (Wellbeing.SOCIAL_EVERY)));
                Wellbeing.updateSocial(state);
            }
            expect(a.social).toBe(80);
            expect(b.social).toBe(80);
            expect(c.social).toBe(40);
            c.social = Wellbeing.LOW - 1;
            var before = Mood.mood(state, c);
            c.social = Wellbeing.LOW + 1;
            expect(Mood.mood(state, c)).toBeGreaterThan(before);
        }

        [Fact(DisplayName = "social > talking is company")]
        public void T003_talking_is_company()
        {
            var state = ScenarioMod.loadScenario(new Scenario { seed = 1, map = ["s.s"] });
            var (a, b) = state.survivors;
            Commands.applyCommand(state, new Command { type = "takeControl", survivorId = a.id });
            expect(Talk.talk(state, b)).toBeNull();
            expect(a.social).toBe(80);
            expect(b.social).toBe(80);
        }
    }

    /// <summary>comfort</summary>
    public class D004_comfort
    {

        [Fact(DisplayName = "comfort > a bed in a finished bedroom beats the floor outdoors, and moves halfway each night")]
        public void T005_a_bed_in_a_finished_bedroom_beats_the_floor_outdoors_and_mov()
        {
            var state = ScenarioMod.loadScenario(new Scenario { seed = 1, map = ["s.......", ".#####..", ".#b..#..", ".#...#..", ".##D##..", "........"] });
            Commands.applyCommand(state, new Command { type = "designateRoom", x = Js.I(3), y = Js.I(3), purpose = "housing" });
            var s = Js.NN(Js.Get(state.survivors, 0));
            var bed = Js.NN(state.furniture.find((f) => f.kind == "bed"));
            var floor = Wellbeing.nightScore(state, s, null);
            s.pos = new Point { x = Js.I(bed.x), y = Js.I(bed.y) };
            var good = Wellbeing.nightScore(state, s, bed.id);
            expect(good).toBeGreaterThan(Wellbeing.HIGH);
            expect(floor).toBeLessThan(Wellbeing.LOW + 20);
            s.comfort = 50;
            Wellbeing.wakeComfort(state, s, bed.id);
            expect(s.comfort).toBe(JsMath.round(((double)((50 + good)) / (2))));
        }

        [Fact(DisplayName = "comfort > sleeping in a bed sets it on waking")]
        public void T006_sleeping_in_a_bed_sets_it_on_waking()
        {
            var state = ScenarioMod.loadScenario(new Scenario { seed = 1, map = ["s.b"] });
            var s = Js.NN(Js.Get(state.survivors, 0));
            s.comfort = 0;
            Commands.applyCommand(state, new Command { type = "setRest", survivorId = s.id, rest = 400 });
            for (var t = 0; (t < 3000) && (s.comfort == 0); t++)
            {
                Tick.tick(state);
            }
            expect(s.comfort).toBeGreaterThan(0);
        }
    }
